import itertools, random
def anti(p,q): return (p[0]-q[0])*(p[1]-q[1])<0
def cl(P,C):
    R=set(C)
    for i in range(len(P)):
        if i in C: continue
        if all(anti(P[i],P[c]) for c in C): R.add(i)
    if not C: return frozenset(range(len(P)))
    return frozenset(R)
def test(N,trials=200):
    bad=0
    for _ in range(trials):
        xs=list(range(1,N+1)); ys=list(range(1,N+1))
        random.shuffle(xs); random.shuffle(ys)
        P=list(zip(xs,ys))
        Rs=set(); loc=0; chains=[]
        for m in range(0,N+1):
            for C in itertools.combinations(range(N),m):
                if any(not anti(P[a],P[b]) for a,b in itertools.combinations(C,2)): continue
                R=cl(P,set(C)); Rs.add(R)
                ok=True
                for q in R:
                    if q in C: continue
                    if cl(P,set(C)|{q})==R: ok=False;break
                if ok: loc+=1
        if loc!=len(Rs): bad+=1
    return bad
for N in range(1,7): print(N,test(N,100))

