class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_b = [[] for _ in range(n + 1)]
        for i, (x, y) in enumerate(conflictingPairs):
            a, b = min(x, y), max(x, y)
            by_b[b].append((a, i))
        gain = [0] * len(conflictingPairs)
        best1 = 0; best2 = 0; cnt1 = 0; pidx = -1
        base = 0
        for r in range(1, n + 1):
            for a, i in by_b[r]:
                if a > best1:
                    best2 = best1
                    best1 = a
                    cnt1 = 1
                    pidx = i
                elif a == best1:
                    cnt1 += 1
                    best2 = best1
                elif a > best2:
                    best2 = a
            base += r - best1
            if cnt1 == 1:
                gain[pidx] += best1 - best2
        return base + max(gain)

