    for i in range(1,n+1):
        seen.add(A[i]); L[i]=len(seen)
    R=[0]*(n+2); seen=set()
    for j in range(n,0,-1):
        seen.add(A[j]); R[j]=len(seen)
    parent=list(range(n+3)); parent[1]=2
    prev=[0]*(n+2); gap=[0]*(n+2)
    first=0; fval=0; tail=0; tailval=0
    last=[0]*(n+2); ans=0
    for j in range(1,n+1):
        if j>=2:
            v=L[j-1]
            while tail and tailval<=v:
                t=tail; pt=prev[t]
                parent[t]=t+1
                if pt==0:
                    tail=0; break
                tailval=tailval+gap[t]; tail=pt
            if tail==0:
                first=j; fval=v; prev[j]=0
            else:
                prev[j]=tail; gap[j]=tailval-v
            tail=j; tailval=v
            p=last[A[j]]; last[A[j]]=j
            q=p+1
            r=q
            while parent[r]!=r:
                parent[r]=parent[parent[r]]
                r=parent[r]
            s0=r
            tailval+=1
