                gap[s0]-=1
                if gap[s0]==0:
                    pr=prev[s0]
                    parent[pr]=pr+1
                    pp=prev[pr]
                    prev[s0]=pp
                    if pp==0:
                        first=s0
                    else:
                        gap[s0]=gap[pr]
        else:
            last[A[j]]=j
        if 2<=j<=n-1:
            v2=fval+R[j+1]
            if v2>ans: ans=v2
    print(ans)
