        m[size+s]=L[s-1]-BIG
    for x in range(size-1,0,-1):
        m[x]=max(m[2*x],m[2*x+1])
    def upd(l,r,v):
        # inclusive l..r
        l0=l+size; r0=r+size
        lo=l0; hi=r0+1
        while lo<hi:
            if lo&1:
                m[lo]+=v; d[lo]+=v; lo+=1
            if hi&1:
                hi-=1; m[hi]+=v; d[hi]+=v
            lo>>=1; hi>>=1
        x=l0>>1
