class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        # Pascal's triangle mod MOD
        C = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD
        # cnt[c] = number of x in [0, n) with popcount c
        cnt = [0] * (n + 2)
        ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                L = n - i - 1
                for t in range(L + 1):
                    cnt[ones + t] = (cnt[ones + t] + C[L][t]) % MOD
                ones += 1
        # g(c): number of operations to reach 1 starting from value c
        def g(c):
            if c == 1:
                return 0
            return 1 + g(bin(c).count('1'))
        ans = 0
        for c in range(1, n + 2):
            if c <= n + 1 and cnt[c] and g(c) <= k - 1:
                ans = (ans + cnt[c]) % MOD
        return ans

