import sys

def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    adj = [0] * n
    idx = 2
    for _ in range(m):
        u = int(data[idx]) - 1
        v = int(data[idx + 1]) - 1
        idx += 2
        adj[u] |= 1 << v
        adj[v] |= 1 << u
    rows = [adj[v] for v in range(n) if adj[v] != 0]
    # Gaussian elimination over GF(2), reduced row echelon form
    pivcols = []
    r = 0
    for c in range(n):
        sel = -1
        for i in range(r, len(rows)):
            if (rows[i] >> c) & 1:
                sel = i
                break
        if sel == -1:
            continue
        rows[r], rows[sel] = rows[sel], rows[r]
        for i in range(len(rows)):
            if i != r and (rows[i] >> c) & 1:
                rows[i] ^= rows[r]
        pivcols.append(c)
        r += 1
    pivset = set(pivcols)
    free = [c for c in range(n) if c not in pivset]
    basis = []
    for f in free:
        vec = 1 << f
        for ri, c in enumerate(pivcols):
            if (rows[ri] >> f) & 1:
                vec |= 1 << c
        basis.append(vec)
    X = [0] * n
    for i, b in enumerate(basis):
        for v in range(n):
            if (b >> v) & 1:
                X[v] |= 1 << i
    if any(x == 0 for x in X):
        print("No")
    else:
        print("Yes")
        print(" ".join(map(str, X)))

main()

