class Solution:
    def lenOfVDiagonal(self, grid):
        n = len(grid); m = len(grid[0])
        dirs = [(1,1),(1,-1),(-1,-1),(-1,1)]
        need = {0:2, 1:2, 2:0}
        def ok(i, j, v):
            return 0 <= i < n and 0 <= j < m and grid[i][j] == v
        B0 = []
        for di, dj in dirs:
            b = [[0]*m for _ in range(n)]
            rows = range(n-1, -1, -1) if di == 1 else range(n)
            cols = range(m-1, -1, -1) if dj == 1 else range(m)
            for i in rows:
                bi = b[i]
                for j in cols:
                    ni, nj = i+di, j+dj
                    if ok(ni, nj, need[grid[i][j]]):
                        bi[j] = 1 + b[ni][nj]
            B0.append(b)
        B1 = []
        for d in range(4):
            di, dj = dirs[d]
            tdi, tdj = dirs[(d+1) % 4]
            b = [[0]*m for _ in range(n)]
            nb0 = B0[(d+1) % 4]
            rows = range(n-1, -1, -1) if di == 1 else range(n)
            cols = range(m-1, -1, -1) if dj == 1 else range(m)
            for i in rows:
                bi = b[i]
                for j in cols:
                    nv = need[grid[i][j]]
                    best = 0
                    ni, nj = i+di, j+dj
                    if ok(ni, nj, nv):
                        best = 1 + b[ni][nj]
                    ti, tj = i+tdi, j+tdj
                    if ok(ti, tj, nv):
                        c = 1 + nb0[ti][tj]
                        if c > best:
                            best = c
                    bi[j] = best
            B1.append(b)
        ans = 0
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    for d in range(4):
                        v = 1 + B1[d][i][j]
                        if v > ans:
                            ans = v
        return ans

