from typing import List
from functools import lru_cache
from math import factorial

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        @lru_cache(maxsize=None)
        def seq(a, b, p):
            if a + b == 0:
                return 1
            res = 0
            if p != 1 and a > 0:
                res += seq(a - 1, b, 1)
            if p != 0 and b > 0:
                res += seq(a, b - 1, 0)
            return res

        def cnt(a, b, p):
            return seq(a, b, p) * factorial(a) * factorial(b)

        rem = list(range(1, n + 1))
        a = (n + 1) // 2
        b = n // 2
        if cnt(a, b, 2) < k:
            return []
        res = []
        last = 2
        for _ in range(n):
            chosen = False
            for v in rem:
                par = v % 2
                if par == last:
                    continue
                na = a - (1 if par == 1 else 0)
                nb = b - (1 if par == 0 else 0)
                c = cnt(na, nb, par)
                if k <= c:
                    res.append(v)
                    rem.remove(v)
                    a, b, last = na, nb, par
                    chosen = True
                    break
                k -= c
            if not chosen:
                return []
        return res

