class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        weights = []
        for i in range(h):
            j = n - 1 - i
            if i == j:
                w = pow(10, i, k)
            else:
                w = (pow(10, i, k) + pow(10, j, k)) % k
            weights.append(w)
        cache = {}
        def trans(w, mask):
            key = (w, mask)
            if key in cache:
                return cache[key]
            res = 0
            for d in range(10):
                s = (d * w) % k
                for r in range(k):
                    if mask >> r & 1:
                        res |= 1 << ((r + s) % k)
            cache[key] = res
            return res
        masks = [0] * (h + 1)
        masks[h] = 1
        for i in range(h - 1, -1, -1):
            masks[i] = trans(weights[i], masks[i + 1])
        need = 0
        digits = []
        for i in range(h):
            w = weights[i]
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                nr = (need - d * w) % k
                if masks[i + 1] >> nr & 1:
                    digits.append(str(d))
                    need = nr
                    break
        s = ''.join(digits)
        return s + s[:n // 2][::-1]

