class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        a = nums
        n = len(a)
        nxt = [n] * n
        st = []
        for i in range(n):
            while st and a[st[-1]] < a[i]:
                nxt[st.pop()] = i
            st.append(i)
        D = [0] * (n + 1)
        for j in range(n - 1, -1, -1):
            D[j] = a[j] * (nxt[j] - j) + D[nxt[j]]
        pre = [0] * (n + 1)
        for i in range(n):
            pre[i + 1] = pre[i] + a[i]
        sp = [list(range(n))]
        j = 1
        while (1 << j) <= n:
            prev = sp[-1]
            half = 1 << (j - 1)
            cur = []
            for i in range(n - (1 << j) + 1):
                x = prev[i]
                y = prev[i + half]
                if a[y] > a[x]:
                    cur.append(y)
                else:
                    cur.append(x)
            sp.append(cur)
            j += 1

        def qmax(l, r):
            length = r - l + 1
            t = length.bit_length() - 1
            x = sp[t][l]
            y = sp[t][r - (1 << t) + 1]
            return y if a[y] > a[x] else x

        def cost(l, r):
            p = qmax(l, r)
            return (D[l] - D[p] + a[p] * (r - p + 1)) - (pre[r + 1] - pre[l])

        ans = 0
        l = 0
        for r in range(n):
            while cost(l, r) > k:
                l += 1
            ans += r - l + 1
        return ans

