class Solution:
    def makeStringGood(self, s: str) -> int:
        n = len(s)
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        INF = float('inf')
        best = INF
        F = max(cnt) + 1
        for f in range(1, F + 1):
            dp = {0: 0}
            for i in range(26):
                a0 = cnt[i]
                nd = {}
                last = (i == 25)
                for c, cost in dp.items():
                    a = a0 + c
                    for k in {0, 0 if last else a}:
                        v = cost + a
                        if nd.get(k, INF) > v:
                            nd[k] = v
                    if a >= f:
                        for k in {0, 0 if last else a - f}:
                            v = cost + a - f
                            if nd.get(k, INF) > v:
                                nd[k] = v
                    else:
                        v = cost + f - a
                        if nd.get(0, INF) > v:
                            nd[0] = v
                dp = nd
            best = min(best, dp.get(0, INF))
        return best

