from functools import lru_cache
def brute(A,B,C):
    cards=A+B+C
    n=len(cards)
    @lru_cache(None)
    def win(state,turn):
        hand=[i for i in range(n) if state[i]==turn]
        for i in hand:
            s=list(state); s[i]=2
            takes=[j for j in range(n) if state[j]==2 and cards[j]<cards[i]]
            if not takes:
                if not win(tuple(s),1-turn): return True
            else:
                for j in takes:
                    s2=list(s); s2[j]=turn
                    if not win(tuple(s2),1-turn): return True
        return False
    st=tuple([0]*len(A)+[1]*len(B)+[2]*len(C))
    return win(st,0)
