import bisect
class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        def find_all(x):
            if not x:
                return list(range(n + 1))
            m = len(x)
            f = [0] * m
            k = 0
            for i in range(1, m):
                while k and x[i] != x[k]:
                    k = f[k - 1]
                if x[i] == x[k]:
                    k += 1
                f[i] = k
            res = []
            k = 0
            for i, ch in enumerate(s):
                while k and ch != x[k]:
                    k = f[k - 1]
                if ch == x[k]:
                    k += 1
                if k == m:
                    res.append(i - m + 1)
                    k = f[k - 1]
            return res
        i = p.index('*')
        j = p.index('*', i + 1)
        pre, mid, suf = p[:i], p[i+1:j], p[j+1:]
        A = find_all(pre)
        B = find_all(mid)
        C = find_all(suf)
        ans = -1
        for a in A:
            k = bisect.bisect_left(B, a + len(pre))
            if k == len(B):
                continue
            b = B[k]
            t = bisect.bisect_left(C, b + len(mid))
            if t == len(C):
                continue
            c = C[t]
            L = c + len(suf) - a
            if ans == -1 or L < ans:
                ans = L
        return ans

