from fractions import Fraction as F
import itertools,sys
def solve(N,M):
    states={}
    lst=[]
    for p in itertools.product(range(M+1),repeat=N):
        for pos in [(-1,0)]+[(i,d) for i in range(N) for d in range(1,p[i]+1)]:
            states[(p,pos)]=len(lst); lst.append((p,pos))
    n=len(lst)
    # equations: E - avg E(next) = 1 ; terminal E=0
    A=[[F(0)]*(n+1) for _ in range(n)]
    for s,(p,pos) in enumerate(lst):
        A[s][s]=F(1)
        if all(x==M for x in p):
            A[s]=[F(0)]*(n+1); A[s][s]=F(1); continue
        A[s][n]=F(1)
        if pos[0]==-1:
            nb=[(i,1) for i in range(N)]
        else:
            i,d=pos
            nb=[(i,d-1) if d-1>0 else (-1,0)]
            if d<M: nb.append((i,d+1))
        w=F(1,len(nb))
        for (i,d) in nb:
            q=list(p)
            if i>=0: q[i]=max(q[i],d)
            A[s][states[(tuple(q),(i,d) if i>=0 else (-1,0))]]-=w
    # gauss
    for c in range(n):
        piv=next(r for r in range(c,n) if A[r][c]!=0)
        A[c],A[piv]=A[piv],A[c]
        inv=1/A[c][c]
        A[c]=[x*inv for x in A[c]]
        for r in range(n):
            if r!=c and A[r][c]!=0:
                f=A[r][c]
                A[r]=[a-f*b for a,b in zip(A[r],A[c])]
    return A[states[(tuple([0]*N),(-1,0))]][n]
