def main():
    data = sys.stdin.read().split()
    n, W = int(data[0]), int(data[1])
    groups = {}
    for i in range(n):
        w = int(data[2 + 2 * i]); v = int(data[3 + 2 * i])
        groups.setdefault(w, []).append(v)
    dp = np.zeros(W + 1, dtype=np.int64)
    for w, vs in groups.items():
        K = W // w
        parts = []
        for v in vs:
            m = min(K, v // 2)
            if m <= 0:
                continue
            ks = np.arange(1, m + 1, dtype=np.int64)
            parts.append(v - (2 * ks - 1))
        if not parts:
            continue
        arr = np.concatenate(parts)
        arr = np.sort(arr)[::-1][:K]
        for x in arr.tolist():
            if x <= 0:
                break
            dp[w:] = np.maximum(dp[w:], dp[:-w] + x)
    print(int(dp[W]))
