from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        INF = float('inf')
        mins = [None] * k
        P = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + nums[i]
        mins[0] = P[0]
        ans = -INF
        for j in range(1, n + 1):
            r = j % k
            if mins[r] is not None:
                v = P[j] - mins[r]
                if v > ans:
                    ans = v
            if mins[r] is None or P[j] < mins[r]:
                mins[r] = P[j]
        return int(ans)

