import math

def main():
    N = int(input())
    M = math.isqrt(N)
    L = max(M, 2)
    sieve = bytearray([1]) * (L + 1)
    sieve[0] = 0
    sieve[1] = 0
    for i in range(2, math.isqrt(L) + 1):
        if sieve[i]:
            sieve[i*i::i] = bytearray(len(range(i*i, L + 1, i)))
    pi = [0] * (L + 1)
    cnt = 0
    for i in range(L + 1):
        if sieve[i]:
            cnt += 1
        pi[i] = cnt
    primes = [i for i in range(2, L + 1) if sieve[i]]
    ans = 0
    # p^8 <= N
    for p in primes:
        if p ** 8 <= N:
            ans += 1
        else:
            break
    # p^2 q^2 <= N with p < q  <=>  p*q <= M
    for p in primes:
        if p * p >= M:
            break
        c = pi[M // p] - pi[p]
        if c > 0:
            ans += c
    print(ans)

main()

