class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        for _ in range(t):
            new = [0] * 26
            new[0] = cnt[25]
            new[1] = (cnt[1 - 1 + 0] if False else 0) + cnt[25]
            for c in range(25):
                new[c + 1] += cnt[c]
            cnt = [x % MOD for x in new]
        return sum(cnt) % MOD

