class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        masks = [1] * n  # bit s set => sum s reachable
        def ok():
            for i in range(n):
                if not (masks[i] >> nums[i]) & 1:
                    return False
            return True
        if ok():
            return 0
        for k, (l, r, v) in enumerate(queries):
            for i in range(l, r + 1):
                masks[i] |= masks[i] << v
            if ok():
                return k + 1
        return -1

