import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        N = 10000
        sieve = [True] * (N + 1)
        sieve[0] = sieve[1] = False
        for i in range(2, int(N ** 0.5) + 1):
            if sieve[i]:
                for j in range(i * i, N + 1, i):
                    sieve[j] = False

        def is_prime(x):
            return sieve[x]

        if is_prime(n) or is_prime(m):
            return -1
        if n == m:
            return n
        L = len(str(n))
        heap = [(n, n)]
        dist = {n: n}
        while heap:
            d, u = heapq.heappop(heap)
            if d > dist.get(u, float('inf')):
                continue
            if u == m:
                return d
            s = str(u).zfill(L)
            for i in range(L):
                digit = int(s[i])
                for delta in (1, -1):
                    nd = digit + delta
                    if 0 <= nd <= 9:
                        t = s[:i] + str(nd) + s[i + 1:]
                        v = int(t)
                        if is_prime(v):
                            continue
                        nc = d + v
                        if nc < dist.get(v, float('inf')):
                            dist[v] = nc
                            heapq.heappush(heap, (nc, v))
        return -1

