def greedy(a):
    h=[]; cost=0
    for x in a:
        if h and x+h[0]<0:
            # pair: x closes an opener m; x becomes opener too (can be re-chosen later)
            m=heapq.heappop(h); cost+=x+m
            heapq.heappush(h,x)  # alternative: x could later be opener
            heapq.heappush(h,-x if False else x)
        else:
            heapq.heappush(h,x)
    return sum(a)-cost
def brute(a):
    NEG=float('-inf')
    # dp[d] = best sum with stack size d ; stack contents matter only via sum, track survivors sum
    dp={0:0}
    for x in a:
        nd={}
        for d,v in dp.items():
            nd[d+1]=max(nd.get(d+1,NEG),v+x)
            if d>0: nd[d-1]=max(nd.get(d-1,NEG),v)
        dp=nd
    return max(dp.values())
