class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        m = n // 2
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        dp = {s: cost[m-1][s[0]] + cost[m][s[1]] for s in states}
        for k in range(1, m):
            L = m - 1 - k
            R = m + k
            new = {}
            for (a, b) in states:
                best = min(v for (pa, pb), v in dp.items() if pa != a and pb != b)
                new[(a, b)] = best + cost[L][a] + cost[R][b]
            dp = new
        return min(dp.values())

